INSERT INTO event_settings (key, value) VALUES ('faq_json', '[{"q":"What is the dress code?","a":"Black Tie Optional. Dress to celebrate."},{"q":"Is parking available?","a":"Yes — on premises for a discounted rate of $10 per night."},{"q":"What time should I arrive?","a":"Doors open 15 minutes before start time. Please arrive early for check-in."},{"q":"Can I bring a guest?","a":"Yes — you can register yourself plus one guest."},{"q":"What should I expect?","a":"A beautiful evening with dinner, live entertainment, inspiring stories, and celebration."},{"q":"What is the Giver Army?","a":"The Giver Army is a community of generous people who give monthly through GiveSendGo to support causes they believe in. For as little as $5 per month, members are the heart of the GiveSendGo mission to share the hope of Jesus through generosity."},{"q":"Why should I join the Giver Army?","a":"Giver Army members are part of an incredible community making a real difference every month. You get exclusive access to events like the VIP Cocktail Hour, an invitation to a private Giver Army Facebook group, direct updates from campaigns you support, and the joy of consistent, impactful giving. Be a part of the generosity movement impacting lives all over the world!"},{"q":"How do I get VIP access?","a":"VIP Cocktail Hour access (6:00–6:45 PM) is exclusive to Giver Army members. Simply select Yes when asked if you are part of the Giver Army during registration, and check the box to attend the VIP Cocktail Hour. Not a member yet? You can join at giverarmy.com."}]');
